#include <stdio.h>
/*
 * ex08：fork 之后到底复制了什么——写时复制(COW)的页表账本
 * 误区：很多人以为 fork 会把父进程内存「整块拷一份」，所以不敢 fork。
 * 真相：fork 只复制「页表」，物理页共享且全部标记为只读；
 *      谁写哪一页，才为谁复制那一页（Copy-On-Write）。
 * 本程序算三种情况下的物理页开销。
 */
int main(void) {
    int pages = 512;            /* 进程占用 512 个物理页（按 4KB/页 = 2MB） */
    int child_writes = 8;       /* 子进程实际写了 8 页 */

    long pt_entries = pages;                 /* 每个进程各有一份页表项 */
    long phys_shared = pages;                /* fork 瞬间：物理页不复制 */
    long phys_after = pages + child_writes;  /* 子进程写了 8 页 -> 才复制 8 页 */
    long naive_copy = pages * 2;             /* 天真实现：直接整块复制 */

    printf("父进程占用 %d 页（%d KB）\n", pages, pages * 4);
    printf("----------------------------------------------------------------\n");
    printf("%-26s %-14s %s\n", "时机", "物理页数", "说明");
    printf("%-26s %-14ld %s\n", "fork 前（仅父进程）", phys_shared, "父进程独享");
    printf("%-26s %-14ld %s\n", "fork 瞬间（COW 标记）", phys_shared, "页表翻倍，物理页不变，全部只读");
    printf("%-26s %-14ld %s\n", "子进程写 8 页之后", phys_after, "只有被写的 8 页被复制");
    printf("%-26s %-14ld %s\n", "若整块复制的做法", naive_copy, "浪费 512 页");
    printf("----------------------------------------------------------------\n");
    printf("节省物理页 = %ld（%.1f%%）\n", naive_copy - phys_after,
           100.0 * (naive_copy - phys_after) / naive_copy);
    printf("结论：fork 贵在「复制页表 + TLB 失效」，不贵在复制数据；\n");
    printf("      所以 fork 后立刻 exec（Redis bgsave、nginx 都是这招）几乎零成本。\n");
    return 0;
}
